pub fn decode(data: &[u8]) -> Result<Record, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let v = decode_record(&mut r)?;
    r.skip_ws();
    if r.pos < r.buf.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(v)
}

// REFUSALS is in the order two of them are chosen between.
pub const REFUSALS: [&str; 12] = ["malformed", "bad_string", "number_spelling", "wrong_type", "bad_timestamp", "depth_exceeded", "duplicate_field", "unknown_field", "missing_field", "bad_schema", "bad_enum", "trailing_bytes"];

pub fn refusal_rank(word: &str) -> i32 {
    match REFUSALS.iter().position(|w| *w == word) {
        Some(i) => i as i32,
        None => -1,
    }
}

#[allow(unused_variables)]
fn service_check_attestation(v: &Attestation) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    Ok(())
}

#[allow(unused_variables)]
fn service_check_record(v: &Record) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    if v.schema != 1 { return r.refuse("bad_schema"); }
    for value in &v.identity { service_check_attestation(value)?; }
    Ok(())
}

#[allow(unused_variables)]
fn service_check_page(v: &Page) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    if v.outcome != "page" && v.outcome != "gap" && v.outcome != "unavailable" && v.outcome != "invalid_request" && v.outcome != "record_too_large" && v.outcome != "corrupt" && v.outcome != "unsupported" { return r.refuse("bad_enum"); }
    for value in &v.records { service_check_record(value)?; }
    Ok(())
}

