/// Common generated framing boundary; implementation owns waiting and identity.
pub use abstraction_frame::FrameTransport;

#[derive(Debug)]
pub struct ServiceError { pub code: String, pub message: String }
#[derive(Debug)]
pub enum CallError<E> {
    /// Transport failure does not establish whether the receiver accepted work.
    Transport(E),
    Refusal(Refusal),
    Dispatch(&'static str),
    Service(ServiceError),
}
fn service_decode<T>(data: &[u8], decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<T, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let value = decode(&mut r)?;
    r.skip_ws();
    if r.pos != data.len() { return r.refuse("trailing_bytes"); }
    Ok(value)
}
fn service_encode<T>(value: &T, check: fn(&T) -> Result<(), Refusal>, encode: fn(&mut Vec<u8>, &T, i32), decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<Vec<u8>, Refusal> {
    check(value)?;
    let mut data = Vec::new();
    encode(&mut data, value, 0);
    service_decode(&data, decode)?;
    Ok(data)
}

#[allow(non_snake_case)]
pub trait Sink {
    type Error;
    fn Write(&self, arg0: Record) -> Result<(), Self::Error>;
}

pub struct SinkClient<T> { transport: T }
impl<T> SinkClient<T> {
    pub fn new(transport: T) -> Self { Self { transport } }
    pub fn transport(&self) -> &T { &self.transport }
}
#[allow(non_snake_case)]
impl<T: FrameTransport> Sink for SinkClient<T> {
    type Error = CallError<T::Error>;
    fn Write(&self, arg0: Record) -> Result<(), Self::Error> {
        let args = OASinkWriteArguments { record: arg0, };
        let arguments = service_encode(&args, service_check_oasinkwritearguments, enc_oasinkwritearguments, decode_oasinkwritearguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.logging/sink@1".into(), method: "Write".into(), arguments };
        let frame = service_encode(&request, service_check_oaserviceframe, enc_oaserviceframe, decode_oaserviceframe).map_err(CallError::Refusal)?;
        self.transport.write_frame(&frame).map_err(CallError::Transport)
    }
}

#[allow(non_snake_case)]
pub trait HistoryReader {
    type Error;
    fn Read(&self, arg0: String, arg1: i64, arg2: i64) -> Result<Page, Self::Error>;
}

pub struct HistoryReaderClient<T> { transport: T }
impl<T> HistoryReaderClient<T> {
    pub fn new(transport: T) -> Self { Self { transport } }
    pub fn transport(&self) -> &T { &self.transport }
}
#[allow(non_snake_case)]
impl<T: FrameTransport> HistoryReader for HistoryReaderClient<T> {
    type Error = CallError<T::Error>;
    fn Read(&self, arg0: String, arg1: i64, arg2: i64) -> Result<Page, Self::Error> {
        let args = OAHistoryReaderReadArguments { cursor: arg0, max_records: arg1, max_bytes: arg2, };
        let arguments = service_encode(&args, service_check_oahistoryreaderreadarguments, enc_oahistoryreaderreadarguments, decode_oahistoryreaderreadarguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.logging/reader@1".into(), method: "Read".into(), arguments };
        let frame = service_encode(&request, service_check_oaserviceframe, enc_oaserviceframe, decode_oaserviceframe).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oaservicereply).map_err(CallError::Refusal)?;
        if reply.version != 1 { return Err(CallError::Dispatch("unknown_version")); }
        if reply.service != "abstraction.logging/reader@1" || reply.method != "Read" { return Err(CallError::Dispatch("mismatched_response")); }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oaserviceerror).map_err(CallError::Refusal)?;
            if error.code.is_empty() { return Err(CallError::Dispatch("invalid_error")); }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oahistoryreaderreadresult).map_err(CallError::Refusal)?;
        Ok(result.value)
    }
}

